// ╔══════════════════════════════════════════════════════════════════╗
// ║  EDIT THIS BLOCK — copy the values from your two 2B workflows.   ║
// ╚══════════════════════════════════════════════════════════════════╝
const CONFIG = {
  // From "2B — WhatsApp AI Sales Agent" → node "HTTP: Send Text" (the part before /message/...).
  EVO_BASE_URL : 'https://YOUR-EVOLUTION-API-HOST',
  // The instance name at the end of that same URL.
  EVO_INSTANCE : 'YOUR-INSTANCE-NAME',

  // From "2B — Meta Comments & DM Agent (FB + IG)" → node "Code: CONFIG".
  GRAPH_VERSION       : 'v26.0',
  FB_PAGE_ID          : 'YOUR-FACEBOOK-PAGE-ID',
  IG_USER_ID          : 'YOUR-INSTAGRAM-USER-ID',
  IG_SEND_VIA_PAGE_ID : true,

  // Meta lets a business answer within 24h of the customer's last message.
  // With the "Human Agent" permission approved for your app, human replies
  // may go out for 7 days: set this to true once Meta approves it.
  USE_HUMAN_AGENT_TAG : false,
};
return [{ json: CONFIG }];

// Turns the desk's reply into the exact request each channel needs.
const cfg = $('Code: CONFIG').first().json;
const b = $('Webhook: Desk Reply').first().json.body || {};
const channel = String(b.channel || '');
const text = String(b.text || '').trim();
if (!text) throw new Error('The desk sent an empty reply.');

const out = { channel, text, message_id: b.message_id, customer_ref: String(b.customer_ref || '') };
if (channel === 'whatsapp') {
  out.number = String(b.phone || String(b.external_id || '').split('@')[0]).replace(/\D/g, '');
  out.url = cfg.EVO_BASE_URL.replace(/\/+$/, '') + '/message/sendText/' + cfg.EVO_INSTANCE;
} else if (channel === 'messenger' || channel === 'instagram') {
  const sendId = channel === 'instagram' && !cfg.IG_SEND_VIA_PAGE_ID ? cfg.IG_USER_ID : cfg.FB_PAGE_ID;
  out.url = 'https://graph.facebook.com/' + cfg.GRAPH_VERSION + '/' + sendId + '/messages';
  out.payload = cfg.USE_HUMAN_AGENT_TAG
    ? { recipient: { id: String(b.external_id) }, message: { text }, messaging_type: 'MESSAGE_TAG', tag: 'HUMAN_AGENT' }
    : { recipient: { id: String(b.external_id) }, message: { text }, messaging_type: 'RESPONSE' };
} else {
  throw new Error('Unknown channel: ' + channel);
}
return [{ json: out }];

// One answer for the desk: did the customer get it?
const prep = $('Code: Prepare').first().json;
const r = $json || {};
let id = null;
let error = null;
if (prep.channel === 'whatsapp') {
  id = (r.key && r.key.id) || null;
  const detail = r.response && r.response.message;
  if (!id) error = Array.isArray(detail) && detail.some((d) => d && d.exists === false)
    ? 'This number is not on WhatsApp.'
    : (detail && JSON.stringify(detail)) || r.error || r.message || 'WhatsApp (Evolution API) did not confirm the message.';
} else {
  id = r.message_id || null;
  if (!id) error = (r.error && (r.error.message || JSON.stringify(r.error))) || 'Meta did not confirm the message (24-hour window, or the page token expired?).';
}
return [{ json: {
  ok: !!id,
  external_message_id: id,
  error: error ? String(error).slice(0, 300) : null,
  customer_ref: prep.customer_ref,
  text: prep.text,
} }];
